SELECT	MENU_KEY AS menuKey, MENU_NAME AS menuName, MENU_ICON AS menuIcon, ADMIN_ID AS adminId, USEYN AS useYn,
		DEFAULT_MENU AS defaultMenu,DEFAULT_DASHBOARD AS defaultDashboard, DATE_FORMAT(UPDATE_DT, '%Y-%m-%d %T' ) AS updateDt
FROM	UI_CUSTOM_DASHBOARD_MENU
WHERE	ADMIN_ID = #{adminId}

AND		USEYN = #{useYn}


AND		DEFAULT_MENU = #{defaultMenu}


AND		MENU_KEY = #{menuKey}

ORDER BY UPDATE_DT DESC

SELECT MENU_KEY
FROM UI_CUSTOM_DASHBOARD_MENU
WHERE MENU_KEY = #{menuKey} AND DEFAULT_DASHBOARD = 'Y';

mapper.update:
UPDATE 	UI_CUSTOM_DASHBOARD_MENU SET DEFAULT_MENU = #{defaultMenu}
WHERE 	ADMIN_ID = #{adminId}

AND		MENU_KEY = ${menuKey}

mapper.select:
SELECT CD.DASH_KEY AS dashKey, CD.DASH_NAME AS dashName, CD.DASH_TYPE AS dashType, CD.DASH_MULTI_X AS dashMultiLeft, CD.DASH_MULTI_Y AS dashMultiRight, CD.DASH_CHART AS dashChart, CD.DASH_CHART_X AS dashChartX, CD.DASH_CHART_Y AS dashChartY, CD.DASH_ICON AS dashIcon, CD.DASH_COLOR AS dashColor, CD.DASH_HTML AS html, CD.DASH_CONDITION AS dashCondition, CD.DASH_COMMENT AS dashComment, CD.ADMIN_ID AS adminId, CD.USEYN AS useYn, adminIds FROM UI_CUSTOM_DASHBOARD CD LEFT JOIN (SELECT P_DASH_KEY, GROUP_CONCAT(ADMIN_ID) as adminIds FROM UI_CUSTOM_DASHBOARD_SHARE GROUP BY P_DASH_KEY) CDS ON CD.DASH_KEY = CDS.P_DASH_KEY WHERE CD.ADMIN_ID = #{adminId}
AND ( CD.DASH_NAME LIKE CONCAT('%', #{searchStr}, '%') OR CD.DASH_COMMENT LIKE CONCAT('%', #{searchStr}, '%') )
AND CD.DASH_KEY = ${dashKey}
AND CD.USEYN = #{useYn}
ORDER BY CD.DASH_KEY

SELECT AD.ADMIN_ID as adminID, AD.ADMIN_NAME AS adminName,
if(AD.ADMIN_EMAIL is null, null, xcndec(#{encryptAlgorithm}, #{encryptSize}, #{encryptKey}, AD.ADMIN_EMAIL)) AS adminEmail,
AD.ADMIN_EMAIL AS adminEmail,
AD.ADMIN_HP AS adminHp, AD.STATUS AS status, AD.WORK_STATUS AS workStatus, AD.ADMIN_TYPE AS adminType, AD.USE_YN AS useYn FROM UI_CUSTOM_DASHBOARD_SHARE CDS LEFT JOIN UI_ADMIN AD ON AD.ADMIN_ID = CDS.ADMIN_ID GROUP BY CDS.ADMIN_ID HAVING count(DISTINCT CASE WHEN CDS.P_DASH_KEY IN
#{item}
THEN CDS.P_DASH_KEY END) = #{total};

SELECT	COUNT(*)
FROM	UI_CUSTOM_DASHBOARD_SHARE
WHERE	ADMIN_ID = #{adminId}

AND		P_DASH_KEY = #{pdashKey}


AND		DASH_KEY = #{dashKey}

SELECT	DASH_KEY
FROM	UI_CUSTOM_DASHBOARD_SHARE
WHERE	P_DASH_KEY = ${dashKey}
AND		ADMIN_ID = #{adminId}

